const http = require('http');
const fs = require('fs');
const path = require('path');
const PORT = 5173;
let ticks = 0;
setInterval(() => { ticks++; console.log('[heartbeat] ticks=' + ticks); }, 500);
const mime = { '.html': 'text/html', '.js': 'application/javascript', '.css': 'text/css', '.json': 'application/json' };

function parseUrl(url) {
  const [pathname, search] = url.split('?');
  const query = {};
  if (search) search.split('&').forEach(p => { const [k, v] = p.split('='); query[decodeURIComponent(k || '')] = decodeURIComponent(v || ''); });
  return { pathname: pathname || '/', query };
}

function collectBody(req) {
  return new Promise((resolve) => {
    const chunks = [];
    req.on('data', c => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks).toString()));
  });
}

const routes = {
  '/': (req, res, { pathname }) => {
    fs.readFile(path.join(__dirname, '/index.html'), (err, data) => {
      if (err) { res.writeHead(500); return res.end(String(err)); }
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  },
  '/index.html': (req, res, { pathname }) => {
    fs.readFile(path.join(__dirname, pathname), (err, data) => {
      if (err) { res.writeHead(404); return res.end(); }
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  },
  '/api/hello': (req, res, { query }) => {
    const name = query.name || 'World';
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: `Hello, ${name}!`, timestamp: Date.now() }));
  },
  '/api/echo': async (req, res) => {
    const body = await collectBody(req);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ received: body, method: req.method }));
  },
  '/api/health': (req, res) => {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', uptime: process.uptime(), ticks }));
  }
};

function serveStatic(staticPath) {
  return (req, res, { pathname }) => {
    const file = path.join(__dirname, pathname);
    const ext = path.extname(file);
    fs.readFile(file, (err, data) => {
      if (err) { res.writeHead(404); return res.end(); }
      res.writeHead(200, { 'Content-Type': mime[ext] || 'text/plain' });
      res.end(data);
    });
  };
}

http.createServer(async (req, res) => {
  const { pathname, query } = parseUrl(req.url || '/');
  const ctx = { pathname, query };
  const handler = routes[pathname] || serveStatic(pathname);
  try {
    const r = handler(req, res, ctx);
    if (r && typeof r.then === 'function') await r;
  } catch (e) {
    res.writeHead(500, { 'Content-Type': 'text/plain' });
    res.end(String(e));
  }
}).listen(PORT, () => console.log('Server http://localhost:' + PORT));
